void
rsa_public_key_init(struct rsa_public_key *key)
{
  mpz_init(key->n);
  mpz_init(key->e);

  /* Not really necessary, but it seems cleaner to initialize all the
   * storage. */
  key->size = 0;
}

void
rsa_public_key_clear(struct rsa_public_key *key)
{
  mpz_clear(key->n);
  mpz_clear(key->e);
}

/* Computes the size, in octets, of a the modulo. Returns 0 if the
 * modulo is too small to be useful, or otherwise appears invalid. */
size_t
_rsa_check_size(mpz_t n)
{
  /* Round upwards */
  size_t size;

  /* Even moduli are invalid, and not supported by mpz_powm_sec. */
  if (mpz_even_p (n))
    return 0;

  size = (mpz_sizeinbase(n, 2) + 7) / 8;

  if (size < RSA_MINIMUM_N_OCTETS)
    return 0;

  return size;
}

int
rsa_public_key_prepare(struct rsa_public_key *key)
{
  key->size = _rsa_check_size(key->n);

  return (key->size > 0);
}

#include "testutils.h"
#include "knuth-lfib.h"

#define MSG1 "None so blind as those who will not see"
#define MSG2 "Fortune knocks once at every man's door"

static void
test_rsa_sign_tr(struct rsa_public_key *pub,
	     struct rsa_private_key *key,
	     unsigned di_length,
	     const uint8_t *di,
	     mpz_t expected)
{
  mpz_t signature;
  struct knuth_lfib_ctx lfib;

  knuth_lfib_init(&lfib, 1111);

  mpz_init(signature);
  mpz_set_ui (signature, 17);
  /* Try bad private key */
  mpz_add_ui(key->p, key->p, 2);

  ASSERT(!rsa_pkcs1_sign_tr(pub, key,
		    &lfib, (nettle_random_func *) knuth_lfib_random,
		    di_length, di, signature));

  mpz_sub_ui(key->p, key->p, 2);

  ASSERT(!mpz_cmp_ui(signature, 17));

  /* Try the good private key */
  ASSERT(rsa_pkcs1_sign_tr(pub, key,
		    &lfib, (nettle_random_func *) knuth_lfib_random,
		    di_length, di, signature));

  if (verbose)
    {
      fprintf(stderr, "rsa-pkcs1-tr signature: ");
      mpz_out_str(stderr, 16, signature);
      fprintf(stderr, "\nrsa-pkcs1-tr expected: ");
      mpz_out_str(stderr, 16, expected);
      fprintf(stderr, "\n");
    }

  ASSERT (mpz_cmp(signature, expected) == 0);

  /* Try bad data */
  ASSERT (!rsa_pkcs1_verify(pub, 16, (void*)"The magick words", signature));

  /* Try correct data */
  ASSERT (rsa_pkcs1_verify(pub, di_length, di, signature));

  /* Try bad signature */
  mpz_combit(signature, 17);
  ASSERT (!rsa_pkcs1_verify(pub, di_length, di, signature));

  mpz_clear(signature);
}


