  mpz_t expected;

  mpz_init(expected);

  rsa_private_key_init(&key);
  rsa_public_key_init(&pub);

  test_rsa_set_key_1(&pub, &key);

  /* Test signatures */
  mpz_set_str(expected,
	      "23bd361a622bc35450a30ae332d8dad050c6bad5cae0b61c5bee29"
