+#else /* !NETTLE_USE_MINI_GMP */
+
+void
+nettle_mpz_powm_sec(mpz_t r, const mpz_t b, const mpz_t e, const mpz_t m)
+{
+  mpz_powm_sec(r, b, e, m);
+}
+
+#endif /* !NETTLE_USE_MINI_GMP */

