  mpz_set(result, b);
  nettle_mpz_powm_sec(result, result, e, m);
  ASSERT(mpz_cmp(result, expected) == 0);

  mpz_clear(result);
  mpz_clear(expected);
}

static int
cmp_sign(int x)
{
  return (x > 0) - (x < 0);
}

static void
check_cmp(const mpz_t a, const mpz_t b)
{
  ASSERT(cmp_sign(nettle_mpz_cmp_sec(a, b)) == cmp_sign(mpz_cmp(a, b)));
  ASSERT(cmp_sign(nettle_mpz_cmp_sec(b, a)) == cmp_sign(mpz_cmp(b, a)));
}

void
test_main(void)
{
  gmp_randstate_t rands;
