  mask = - (negative & (mp_limb_t) (nonzero != 0));
  mpn_sub_n(sub, mp, base, n);
  for (i = 0; i < n; i++)
    base[i] = (base[i] & ~mask) | (sub[i] & mask);

  ct_limbs_zero(one, n);
  one[0] = 1;
  ct_to_mont(one, mp, n, sub);

  ct_to_mont(base, mp, n, sub);
  for (i = 0; i < n; i++)
