  one[0] = 1;
  ct_mont_mul(prod, acc, one, mp, m0inv, n, tp, sub);

  mpz_import(r, n, -1, sizeof(mp_limb_t), 0, 0, prod);

  free(sub);
  free(tp);
  free(ep);
  free(prod);
  free(acc);
  free(one);
  free(base);
  free(bp);
  free(mp);
}

